from fractions import Fraction
import math

def can_reach_one(m, n, max_elements=1000):
    start_set = {Fraction(m, n), Fraction(n, m)}
    visited = set(start_set)
    queue = list(start_set)

    idx = 0
    while idx < len(queue):
        x = queue[idx]
        idx += 1

        for y in visited:
            if x == y: continue

            # Arithmetic mean
            am = (x + y) / 2
            if am == 1: return True
            if am not in visited and len(visited) < max_elements:
                visited.add(am)
                queue.append(am)

            # Harmonic mean
            hm = (2 * x * y) / (x + y)
            if hm == 1: return True
            if hm not in visited and len(visited) < max_elements:
                visited.add(hm)
                queue.append(hm)
    return False

# Test for small m, n
results = []
for m in range(1, 20):
    for n in range(1, m + 1):
        if math.gcd(m, n) == 1:
            if can_reach_one(m, n):
                results.append(m + n)

print(sorted(list(set(results))))

from fractions import Fraction
import math

def can_reach_one(m, n, max_elements=500):
    start_set = {Fraction(m, n), Fraction(n, m)}
    visited = set(start_set)
    queue = list(start_set)

    idx = 0
    while idx < len(queue):
        x = queue[idx]
        idx += 1

        # We need to iterate over a copy of the visited set to avoid modification errors
        # But to be efficient, we only check against the numbers we've seen so far.
        for y in list(visited):
            if x == y: continue

            am = (x + y) / 2
            if am == 1: return True
            if am not in visited and len(visited) < max_elements:
                visited.add(am)
                queue.append(am)

            hm = (2 * x * y) / (x + y)
            if hm == 1: return True
            if hm not in visited and len(visited) < max_elements:
                visited.add(hm)
                queue.append(hm)
    return False

results = []
for m in range(1, 21):
    for n in range(1, m + 1):
        if math.gcd(m, n) == 1:
            if can_reach_one(m, n):
                results.append(m + n)

print(sorted(list(set(results))))

