def get_reachable(m, n, max_denom=1000):
    initial_set = {Fraction(m, n), Fraction(n, m)}
    reachable = set(initial_set)

    changed = True
    while changed:
        changed = False
        current_elements = list(reachable)
        for i in range(len(current_elements)):
            for j in range(i, len(current_elements)):
                x = current_elements[i]
                y = current_elements[j]

                # AM
                am = (x + y) / 2
                if am not in reachable and am.denominator <= max_denom:
                    reachable.add(am)
                    changed = True

                # HM
                if x + y != 0:
                    hm = (2 * x * y) / (x + y)
                    if hm not in reachable and hm.denominator <= max_denom:
                        reachable.add(hm)
                        changed = True
        if 1 in reachable:
            return True
    return 1 in reachable

