from collections import deque

def can_reach_one(m, n, max_elements=10, max_denominator=100):
    start_set = frozenset([Fraction(m, n), Fraction(n, m)])
    queue = deque([start_set])
    visited = {start_set}

    while queue:
        current_set = queue.popleft()
        if Fraction(1, 1) in current_set:
            return True

        if len(current_set) >= max_elements:
            continue

        current_list = list(current_set)
        for i in range(len(current_list)):
            for j in range(i + 1, len(current_list)):
                x = current_list[i]
                y = current_list[j]

                # Arithmetic mean
                a = (x + y) / 2
                if a.denominator <= max_denominator:
                    new_set = frozenset(current_set | {a})
                    if new_set not in visited:
                        visited.add(new_set)
                        queue.append(new_set)

                # Harmonic mean
                h = 2 * x * y / (x + y)
                if h.denominator <= max_denominator:
                    new_set = frozenset(current_set | {h})
                    if new_set not in visited:
                        visited.add(new_set)
                        queue.append(new_set)
    return False

