def get_next_states(numbers):
    next_states = []
    for i in range(len(numbers)):
        for j in range(i + 1, len(numbers)):
            x, y = numbers[i], numbers[j]
            # Arithmetic mean
            am = (x + y) / 2
            next_states.append(tuple(sorted(list(numbers) + [am])))
            # Harmonic mean
            hm = (2 * x * y) / (x + y)
            next_states.append(tuple(sorted(list(numbers) + [hm])))
    return next_states

def can_reach_one(m, n, max_depth=10):
    # numbers are fractions
    from fractions import Fraction
    start_numbers = tuple(sorted([Fraction(m, n), Fraction(n, m)]))
    queue = [(start_numbers, 0)]
    visited = {start_numbers}

    while queue:
        current_numbers, depth = queue.pop(0)
        if Fraction(1) in current_numbers:
            return True
        if depth < max_depth:
            for next_numbers in get_next_states(current_numbers):
                if next_numbers not in visited:
                    visited.add(next_numbers)
                    queue.append((next_numbers, depth + 1))
    return False

