from fractions import Fraction

def find_reachable(m, n, max_depth=5):
    x = Fraction(m, n)
    y = Fraction(n, m)
    reachable = {x, y}
    queue = [(x, y)]

    # We need to be careful about the size of reachable
    # Let's try to see if 1 is reachable in a few steps
    # A number is reachable if it's an AM or HM of two numbers in the set.
    # However, the set grows. Let's use a simpler approach.
    # Let S be the set of reachable numbers.
    # Initially S = {m/n, n/m}
    # In each step, we can add A(u, v) or H(u, v) for u, v in S.

    S = {x, y}
    for _ in range(max_depth):
        new_S = set()
        for u in S:
            for v in S:
                am = (u + v) / 2
                hm = (2 * u * v) / (u + v)
                if am == 1 or hm == 1:
                    return True
                new_S.add(am)
                new_S.add(hm)
        S.update(new_S)
        if len(S) > 1000: # Limit the size of S to avoid explosion
            break
    return False

